  "syndicats-assain":{short:"Qui gère collecte et traitement des eaux usées",what:"Elle cartographie les structures compétentes pour l’assainissement collectif ou non collectif.",read:"Elle permet d’identifier le service responsable selon la commune ; elle ne représente pas directement les réseaux enterrés."},
  "syndicats-riviere":{short:"Qui entretient et restaure les rivières",what:"Elle montre les syndicats intervenant sur les cours d’eau, les bassins versants et la compétence GEMAPI.",read:"Une commune peut relever de plusieurs syndicats selon les rivières ou bassins concernés ; la fiche énumère ces organismes."},
  police:{short:"Service compétent pour instruire la police de l’eau",what:"La couche associe chaque tronçon au service chargé de la police de l’eau.",read:"Elle renseigne l’organisation administrative du contrôle des travaux et usages ayant un impact sur les milieux aquatiques."},
  "sup-as1":{short:"Périmètres réglementaires de protection des eaux",what:"La servitude AS1 protège les captages d’eau destinée à la consommation humaine et certaines ressources minérales.",read:"Les périmètres peuvent imposer des interdictions ou prescriptions d’usage. La fiche officielle est référencée même lorsque sa géométrie n’est pas directement réutilisable."},
  "sup-a5":{short:"Servitudes liées aux canalisations publiques",what:"La servitude A5 concerne certaines canalisations publiques d’eau potable et d’assainissement.",read:"Elle peut encadrer l’accès, l’entretien et les constructions à proximité des ouvrages ; la source de référence est le Géoportail de l’urbanisme."},
  "assain-prix":{short:"Tarif de collecte et traitement des eaux usées",what:"Ce jeu décrit le prix du service d’assainissement collectif pour l’usager.",read:"Il complète le prix de l’eau potable. La ressource cartographique est conservée au catalogue même lorsque son téléchargement est indisponible."},
  "hydro-live":{short:"Hauteur et débit mesurés dans les rivières",what:"Les stations hydrométriques suivent en continu le niveau et, selon la station, le débit des cours d’eau.",read:"La fiche affiche la dernière hauteur brute disponible et son heure. Une hausse ou baisse doit être interprétée par rapport aux caractéristiques propres de la station."},
  "river-live":{short:"Analyses physico-chimiques des cours d’eau",what:"Ces stations centralisent les prélèvements de qualité des rivières : nutriments, oxygène, matières, micropolluants et autres paramètres publiés dans Naïades.",read:"La station localise le suivi. Les résultats varient selon les campagnes, les paramètres recherchés et les dates d’analyse."},
  "groundwater-bodies":{short:"Les aquifères présents sous le territoire",what:"Ces polygones représentent les masses d’eau souterraines utilisées pour l’évaluation de la Directive-cadre sur l’eau.",read:"L’horizon 1 est le niveau le plus proche de la surface ; les horizons 2 à 4 représentent des masses progressivement plus profondes. Plusieurs nappes peuvent donc se superposer au même endroit."},
  piezometers:{short:"Profondeur et cote du niveau de la nappe",what:"Un piézomètre est un forage d’observation qui mesure la hauteur de l’eau souterraine en un point précis.",read:"La fiche affiche la dernière cote en mètres NGF, la profondeur publiée, l’évolution récente et la nappe suivie. Six stations ont publié une mesure depuis 2025 dans le Val-d’Oise."},
  groundwater:{short:"Analyses chimiques des nappes souterraines",what:"Ces points de suivi renseignent la qualité des eaux souterraines : nitrates, pesticides, minéraux et autres substances analysées.",read:"La fiche identifie le point, la masse d’eau, la profondeur et la période de mesure. La présence d’un point ne signifie pas qu’il alimente le réseau potable."},
  fish:{short:"Espèces et peuplements observés par pêche scientifique",what:"Les stations piscicoles correspondent à des opérations de pêche électrique menées par l’OFB et ses partenaires.",read:"Les observations permettent de connaître les espèces présentes, les effectifs et les tailles, puis d’évaluer l’état des peuplements dans le temps."},
  hydrobio:{short:"Invertébrés, diatomées, macrophytes et poissons",what:"Le suivi hydrobiologique observe les organismes vivant dans les cours d’eau et calcule des indices biologiques.",read:"Ces communautés réagissent à la pollution et à la dégradation des habitats ; leur composition renseigne donc la qualité écologique sur une période plus longue qu’une mesure ponctuelle."},
  etiage:{short:"Présence ou absence d’écoulement en période sèche",what:"Le réseau Onde suit visuellement les petits cours d’eau en été, notamment là où il n’existe pas de station de débit automatique.",read:"L’observation distingue l’écoulement visible, l’écoulement faible, la rupture d’écoulement et l’assec. Elle aide à repérer la tension sur la ressource et les milieux aquatiques."}
