function makeCharts(){state.charts.forEach(c=>c.destroy());const d=chartData(),font={family:"Marianne"},tooltip={titleFont:font,bodyFont:font},common={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip},scales:{x:{grid:{display:false},ticks:{font}},y:{beginAtZero:true,grid:{color:"#edf1f3"},ticks:{font}}}};
  document.getElementById("dashboardKpis").innerHTML=[[`${d.quality.reduce((a,b)=>a+b,0)}`,"tronçons évalués","État écologique DCE"],[`${Math.round((d.quality[0]||0)/(d.quality.reduce((a,b)=>a+b,0)||1)*100)} %`,"en bon état","Part des tronçons classés"],[`${d.weightedPrice.toFixed(2).replace(".",",")} €`,"prix moyen pondéré / m³","Pondéré par la population"],[`${d.networks.reduce((a,b)=>a+b,0)}`,"points dans les réseaux","Comptages non dédoublonnés"],["7","masses d’eau souterraines","Réparties sur 4 horizons"],["3","zones d’alerte sécheresse","Zonage de référence"]].map(([v,l,s])=>`<article><strong>${v}</strong><span>${l}</span><small>${s}</small></article>`).join("");
  state.charts.push(new Chart(document.getElementById("qualityChart"),{type:"bar",data:{labels:Object.values(qualityLabels),datasets:[{label:"Tronçons",data:d.quality,backgroundColor:Object.values(qualityColors),borderRadius:4,yAxisID:"y"},{label:"Longueur (km)",data:d.qualityKm,backgroundColor:Object.values(qualityColors).map(c=>c+"77"),borderWidth:1,borderColor:Object.values(qualityColors),borderRadius:4,yAxisID:"y1"}]},options:{...common,plugins:{legend:{display:true,position:"bottom",labels:{boxWidth:12,font}},tooltip},scales:{x:{grid:{display:false},ticks:{font}},y:{beginAtZero:true,position:"left",title:{display:true,text:"Tronçons",font},grid:{color:"#edf1f3"},ticks:{font}},y1:{beginAtZero:true,position:"right",title:{display:true,text:"Kilomètres",font},grid:{display:false},ticks:{font}}}}}));
  state.charts.push(new Chart(document.getElementById("priceChart"),{type:"bar",data:{labels:["< 2,50 €","2,50–3 €","3–4 €","≥ 4 €"],datasets:[{data:d.bins,backgroundColor:["#d9d4f5","#9b8cdc","#6554c0","#3f2c80"],borderRadius:5}]},options:common}));
  state.charts.push(new Chart(document.getElementById("networkChart"),{type:"bar",data:{labels:["Hydrométrie","Qualité rivières","Poissons","Hydrobiologie","Qualité nappes"],datasets:[{data:d.networks,backgroundColor:["#0878d1","#009f91","#18753c","#d13b75","#8155a5"],borderRadius:5}]},options:{...common,indexAxis:"y"}}));
  state.charts.push(new Chart(document.getElementById("aquiferChart"),{type:"doughnut",data:{labels:["H1 · proche surface","H2","H3","H4 · profond"],datasets:[{data:d.aquifers,backgroundColor:["#22a7bd","#6673c8","#8a52b1","#bb477e"],borderColor:"#fff",borderWidth:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom",labels:{boxWidth:10,font}},tooltip}}}));
  state.charts.push(new Chart(document.getElementById("piezoChart"),{type:"bar",data:{labels:d.piezos.map(f=>f.properties.nom_commune),datasets:[{label:"Profondeur du forage (m)",data:d.piezos.map(f=>Number(f.properties.profondeur_investigation)||0),backgroundColor:"#00a7b5",borderRadius:5,yAxisID:"y"},{label:"Mesures disponibles",type:"line",data:d.piezos.map(f=>Number(f.properties.nb_mesures_piezo)||0),borderColor:"#000091",backgroundColor:"#000091",tension:.25,yAxisID:"y1"}]},options:{...common,plugins:{legend:{display:true,position:"bottom",labels:{boxWidth:12,font}},tooltip},scales:{x:{grid:{display:false},ticks:{font}},y:{beginAtZero:true,title:{display:true,text:"Profondeur (m)",font},ticks:{font}},y1:{beginAtZero:true,position:"right",grid:{display:false},title:{display:true,text:"Nombre de mesures",font},ticks:{font}}}}}));
  state.charts.push(new Chart(document.getElementById("governanceChart"),{type:"bar",data:{labels:["Eau potable","Assainissement","Rivières"],datasets:[{data:d.governance,backgroundColor:["#0878d1","#8155a5","#009f91"],borderRadius:5}]},options:common}));
  state.charts.push(new Chart(document.getElementById("historyChart"),{type:"line",data:{labels:d.decades,datasets:[{label:"Qualité des rivières",data:d.riverHistory,borderColor:"#009081",backgroundColor:"#00908122",fill:true,tension:.25},{label:"Hydrobiologie",data:d.hydrobioHistory,borderColor:"#c43c7a",backgroundColor:"#c43c7a22",fill:true,tension:.25}]},options:{...common,plugins:{legend:{display:true,position:"bottom",labels:{boxWidth:12,font}},tooltip}}}));
  const good=d.quality[0]||0,total=d.quality.reduce((a,b)=>a+b,0),pct=Math.round(good/(total||1)*100),goodKm=d.qualityKm[0]||0,totalKm=d.qualityKm.reduce((a,b)=>a+b,0);document.getElementById("insightValue").textContent=`${pct} %`;document.getElementById("insightText").textContent=`des tronçons évalués sont en bon état, soit ${goodKm.toLocaleString("fr-FR")} km sur ${totalKm.toLocaleString("fr-FR")} km recensés. ${d.quality[1]||0} tronçons sont en état moyen.`
}
async function init(){renderLayers();renderSources();const layerList=document.getElementById("layerList");layerList.scrollTop=0;await loadCommunes();await Promise.allSettled(sources.filter(s=>s.file).map(loadSource));await Promise.allSettled(sources.filter(s=>s.active).map(s=>setLayer(s,true)));layerList.scrollTop=0;requestAnimationFrame(()=>{layerList.scrollTop=0});document.getElementById("mapStatus").textContent="19 couches cartographiques prêtes · 3 sources documentaires référencées"}
document.getElementById("searchButton").onclick=search;document.getElementById("searchInput").addEventListener("keydown",e=>{if(e.key==="Enter")search()});document.getElementById("resetView").onclick=()=>state.territory?map.fitBounds(state.territory.getBounds(),{padding:[10,10]}):map.fitBounds(BOUNDS_95,{padding:[8,8]});document.getElementById("resetPanel").onclick=()=>document.getElementById("resetView").click();document.getElementById("closeDetail").onclick=()=>document.getElementById("detailPanel").classList.remove("open");document.getElementById("clearLayers").onclick=()=>sources.forEach(s=>{const e=document.getElementById(`layer-${s.id}`);if(e.checked){e.checked=false;setLayer(s,false)}});document.getElementById("openSources").onclick=()=>document.getElementById("sourcesDialog").showModal();document.getElementById("openDashboard").onclick=async()=>{const button=document.getElementById("openDashboard"),label=button.textContent;button.disabled=true;button.textContent="Préparation…";await Promise.allSettled(["hydro-live","river-live","fish","hydrobio","groundwater","piezometers"].map(id=>loadSource(sources.find(s=>s.id===id))));makeCharts();document.getElementById("dashboardDialog").showModal();button.disabled=false;button.textContent=label};document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());document.querySelectorAll(".map-kpis button").forEach(b=>b.onclick=()=>{const s=sources.find(x=>x.id===b.dataset.focus);const e=document.getElementById(`layer-${s.id}`);if(!e.checked){e.checked=true;setLayer(s,true)}});document.querySelectorAll("[data-basemap]").forEach(b=>b.onclick=()=>{const id=b.dataset.basemap;if(id===state.basemap)return;map.removeLayer(baseLayers[state.basemap]);baseLayers[id].addTo(map);baseLayers[id].bringToBack();state.basemap=id;document.querySelectorAll("[data-basemap]").forEach(x=>x.classList.toggle("active",x===b))});
const mobileLayers=document.getElementById("mobileLayers"),layerSidebar=document.getElementById("layerSidebar");mobileLayers.onclick=()=>{const open=layerSidebar.classList.toggle("open");mobileLayers.setAttribute("aria-expanded",String(open));mobileLayers.textContent=open?"Fermer":"Données"};
init();
